async function commit(next:Trip){if(readonly||saving.current||conflict)return false;const parsed=tripSchema.safeParse(next);if(!parsed.success){notify(parsed.error.issues[0].code==='custom'?parsed.error.issues[0].message:'입력 값을 확인하세요. 이름, 날짜, 좌표와 금액은 허용 범위 안에 있어야 합니다.');return false;}next=parsed.data;const prev=tripRef.current;tripRef.current=next;setTrip(next);setRoute(null);if(sample){try{localStorage.setItem('triplan-sample-v1',JSON.stringify(next));setSave('샘플 · 이 기기에 저장됨');}catch{tripRef.current=prev;setTrip(prev);setSave('저장 실패 · 브라우저 저장 공간을 확인하세요.');notify('브라우저 저장 공간에 접근할 수 없어 변경을 저장하지 못했습니다.');return false;}return true;}saving.current=true;setBusy(true);setSave('저장 중…');try{const d=await api('trips/'+trip.id,'PUT',{trip:next,version:versionRef.current});versionRef.current=d.version;setVersion(d.version);setSave('서버 저장 완료');return true;}catch(e){if((e as {status:number}).status===409){setConflict(true);setSave('변경 충돌 · 내 변경안이 보존되어 있습니다.');}else{tripRef.current=prev;setTrip(prev);setSave('저장 실패');}notify((e as Error).message);return false;}finally{saving.current=false;setBusy(false);}}
